  app.get('/api/inventory/transfers',authRequired,async(req,res,next)=>{try{const ids=await companyIds(req);const params=[req.user.tenant_id,ids];let filter='';for(const [key,column] of [['kind','t.operation_kind'],['state','t.state'],['warehouseId','t.warehouse_id']])if(text(req.query[key])){params.push(text(req.query[key]));filter+=` AND ${column}=$${params.length}`;}if(text(req.query.q)){params.push(`%${text(req.query.q)}%`);filter+=` AND (t.transfer_no ILIKE $${params.length} OR COALESCE(t.source_document_no,'') ILIKE $${params.length} OR COALESCE(bp.name,'') ILIKE $${params.length})`;}const{rows}=await pool.query(`SELECT t.*,ot.name AS operation_type_name,w.name AS warehouse_name,bp.name AS partner_name,sl.name AS source_location_name,dl.name AS destination_location_name,(SELECT COUNT(*) FROM inventory_transfer_lines l WHERE l.transfer_id=t.id)::int AS line_count,(SELECT COALESCE(SUM(CASE WHEN l.done_quantity>0 THEN l.done_quantity ELSE l.planned_quantity END),0) FROM inventory_transfer_lines l WHERE l.transfer_id=t.id)::numeric AS total_quantity FROM inventory_transfers t LEFT JOIN inventory_operation_types ot ON ot.id=t.operation_type_id JOIN warehouses w ON w.id=t.warehouse_id LEFT JOIN business_partners bp ON bp.id=t.partner_id LEFT JOIN mrp_locations sl ON sl.id=t.source_location_id LEFT JOIN mrp_locations dl ON dl.id=t.destination_location_id WHERE t.tenant_id=$1 AND t.company_id=ANY($2::uuid[])${filter} ORDER BY t.scheduled_date DESC,t.created_at DESC`,params);res.json(rows.map(camel));}catch(error){next(error);}});
